import system
import csv
from java.io import StringWriter
import traceback

logger = system.util.getLogger("scanKeywordView")

hits = self.view.custom.hits or []

if not hits:
    system.perspective.sendMessage(
        'showWarningToast',
        {'message': 'No hits to export.'}
    )
    return


rawKeywords = (self.view.custom.keyword or "").strip()
if rawKeywords:
    firstKeyword = rawKeywords.split(",")[0].strip().replace(" ", "_")
else:
    firstKeyword = "keyword_scan"

filename = "%s_detailed_report.csv" % firstKeyword

def prettyPath(resPath):
    """Convert internal resourcePath to the nice style used in your report."""
    resPath = resPath or ""
    if resPath.startswith('com.inductiveautomation.perspective/views/'):
        p = resPath.replace('com.inductiveautomation.perspective/views/', '').replace('/view.json', '')
        return p  # e.g. kanoa/mes/asset/operation/main
    elif resPath.startswith('ignition/script-python/'):
        return resPath.replace('ignition/script-python/', 'scripts/')
    elif resPath.startswith('ignition/named-query/'):
        return resPath.replace('ignition/named-query/', 'namedQueries/')
    elif resPath.startswith('ignition/tags/'):
        return resPath.replace('ignition/tags/', 'tags/')
    elif resPath.startswith('com.inductiveautomation.perspective/session-scripts/'):
        return resPath.replace('com.inductiveautomation.perspective/session-scripts/', 'sessionScripts/')
    elif resPath.startswith('com.inductiveautomation.perspective/session-props/'):
        return resPath.replace('com.inductiveautomation.perspective/session-props/', 'sessionProps/')
    return resPath

try:
    # Columns to match your oeeType_detailed_report.csv
    headers = ["Project", "ResourceType", "ResourcePath", "Line", "Snippet"]

    sw = StringWriter()
    writer = csv.writer(sw)

    # Header row
    writer.writerow(headers)

    # Data rows
    for h in hits:
        project      = h.get("project", "")
        resourceType = h.get("resourceType", "")
        rawPath      = h.get("resourcePath", "")
        line         = h.get("line", "")
        snippet      = h.get("snippet", "")

        displayPath = prettyPath(rawPath)

        row = [
            unicode(project),
            unicode(resourceType),
            unicode(displayPath),
            unicode(line),
            unicode(snippet),
        ]
        writer.writerow(row)

    csvText = sw.toString()

    # Download as CSV (Excel opens this perfectly)
    system.perspective.download(
        filename=filename,
        data=csvText,
        mimeType="text/csv"
    )

    logger.info("Exported %d hits to %s" % (len(hits), filename))

except:
    msg = "Failed to export CSV:\n%s" % traceback.format_exc()
    logger.error(msg)
    system.perspective.sendMessage(
        'showWarningToast',
        {'message': 'Failed to export. See logs.'}
    )
